#include <iostream>
#include <string>

int main() {
    using namespace std;
    unsigned N;
    cin >> N;
    string S;
    cin >> S;

    unsigned Q;
    cin >> Q;

    // 変換前と変換後の文字列を作る
    string from, to;
    // すべての英小文字が含まれる文字列で初期化
    from = to = "abcdefghijklmnopqrstuvwxyz"s;

    for (unsigned i = 0; i < Q; ++i) {
        char c, d;
        cin >> c >> d;
        for (auto &&m : to)
            if (m == c) // c があったら
                m = d; // d に変換
    }

    for (const auto c : S)
        for (unsigned i = 0; i < 26; ++i)
            if (c == from[i]) // 変換前の文字から
                cout << to[i]; // 変換後の文字を求める
    cout << endl;

    return 0;
}

#include <iostream>
#include <string>
#include <optional>
#include <vector>
#include <utility>

int main() {
    using namespace std;
    unsigned N;
    cin >> N;
    string S;
    cin >> S;

    unsigned Q;
    cin >> Q;

    // root[c] := 文字 c に対応する根
    // parent[i] := 頂点 i の親
    vector<optional<unsigned>> root(26), parent(N);

    for (unsigned i = 0; i < N; ++i) {
        const auto c = S[i] - 'a';
        if (root[c]) // c の根があれば
            parent[*root[c]] = i; // 今の c の根の親を i に
        root[c] = i; // c の根を i に
    }

    for (unsigned i = 0; i < Q; ++i) {
        char c, d;
        cin >> c >> d;
        c -= 'a';
        d -= 'a';

        if (c == d) // c = d なら
            continue; // 何もしない

        if (!root[c]) // いま c がなければ
            continue; // 何もしない

        if (!root[d]) { // いま d がなければ
            swap(root[d], root[c]); // c の根が新しく d の根になる
            continue;
        }

        // どちらもあれば
        parent[*exchange(root[c], nullopt)] = *root[d]; // c の根を d の根の子にし、c に対応する連結成分がなくなる
    }

    vector<optional<char>> result(N);
    for (unsigned c = 0; c < 26; ++c)
        if (root[c])
            result[*root[c]] = c + 'a'; // それぞれの根はそれぞれの文字に

    for (unsigned i = 0; i < N; ++i){
        if (!result[i]) { // まだ求まっていなければ
            vector<unsigned> index;
            auto now = i;
            while (!result[now]) // 値がわかるところまで
                index.emplace_back(exchange(now, *parent[now])); // 親をたどって
            for (const auto j : index)
                result[j] = result[now]; // たどった頂点の値を確定する
        }
        cout << *result[i];
    }
    cout << endl;

    return 0;
}
